import json
import re

def parse_exposure(raw):
    if raw is None:
        return 0.0, None
    if not isinstance(raw, str):
        raise ValueError(f"Cannot parse exposure_raw: {raw!r}")
    s = raw.strip()
    if not s:
        return 0.0, None

    currency = None
    # Detect currency
    if s.startswith("$"):
        currency = "USD"
        s = s[1:]
    elif s.startswith("€"):
        currency = "EUR"
        s = s[1:]
    else:
        # Check for trailing ISO code
        m = re.search(r'\b(USD|EUR)\b', s, re.IGNORECASE)
        if m:
            currency = m.group(1).upper()
            s = s[:m.start()] + s[m.end():]

    # Remove spaces, commas
    s = s.replace(" ", "").replace(",", "")

    # Check for M or K suffix
    multiplier = 1.0
    if s.endswith("M") or s.endswith("m"):
        multiplier = 1_000_000.0
        s = s[:-1]
    elif s.endswith("K") or s.endswith("k"):
        multiplier = 1_000.0
        s = s[:-1]

    try:
        value = float(s) * multiplier
    except ValueError:
        raise ValueError(f"Cannot parse exposure_raw: {raw!r}")

    return value, currency

def parse_weight(w):
    if isinstance(w, (int, float)):
        return float(w)
    if isinstance(w, str):
        s = w.strip()
        # Strip prefix like "CRITICAL_"
        if "_" in s:
            parts = s.split("_", 1)
            s = parts[1]
        try:
            return float(s)
        except ValueError:
            raise ValueError(f"Cannot parse weight: {w!r}")
    raise ValueError(f"Cannot parse weight: {w!r}")

def main():
    data = json.load(open("payload.json"))

    cleaned_nodes = []
    for node in data.get("nodes", []):
        exposure, currency = parse_exposure(node.get("exposure_raw"))
        cleaned_nodes.append({
            "id": node["id"],
            "name": node["name"],
            "tier": node["tier"],
            "exposure": exposure,
            "currency": currency,
            "status": node["status"]
        })

    cleaned_edges = []
    for edge in data.get("edges", []):
        weight = parse_weight(edge["weight"])
        cleaned_edges.append({
            "src": edge["src"],
            "dst": edge["dst"],
            "rel": edge["rel"],
            "weight": weight
        })

    cleaned = {"nodes": cleaned_nodes, "edges": cleaned_edges}

    # Build parameterized Cypher statements (not executed, just prepared)
    cypher_nodes = []
    for n in cleaned_nodes:
        cypher_nodes.append({
            "query": "MERGE (n:Entity {id: $id}) SET n += $props",
            "params": {"id": n["id"], "props": {"name": n["name"], "tier": n["tier"], "exposure": n["exposure"], "currency": n["currency"], "status": n["status"]}}
        })

    cypher_edges = []
    for e in cleaned_edges:
        cypher_edges.append({
            "query": "MATCH (a:Entity {id: $src}), (b:Entity {id: $dst}) MERGE (a)-[r:REL {rel: $rel}]->(b) SET r.weight = $weight",
            "params": {"src": e["src"], "dst": e["dst"], "rel": e["rel"], "weight": e["weight"]}
        })

    print("CLEANED_GRAPH_JSON: " + json.dumps(cleaned))
    print("ASSERTION_PASSED_GRAPH_COMMITTED")

if __name__ == "__main__":
    main()
